import{_ as a,C as d,o as s,c as n,j as t,a as o,E as i,ag as c}from"./chunks/framework.HG0H2VLS.js";const f=JSON.parse('{"title":"ImportScreen","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/import-screen.md","filePath":"cc-templates/import-screen.md"}'),l={name:"cc-templates/import-screen.md"};function p(h,e,m,u,g,w){const r=d("ComponentDemo");return s(),n("div",null,[e[0]||(e[0]=t("hr",null,null,-1)),e[1]||(e[1]=t("h2",{id:"title-importscreen",tabindex:"-1"},[o("title: ImportScreen "),t("a",{class:"header-anchor",href:"#title-importscreen","aria-label":'Permalink to "title: ImportScreen"'},"​")],-1)),e[2]||(e[2]=t("h1",{id:"importscreen",tabindex:"-1"},[o("ImportScreen "),t("a",{class:"header-anchor",href:"#importscreen","aria-label":'Permalink to "ImportScreen"'},"​")],-1)),e[3]||(e[3]=t("blockquote",null,[t("p",null,"the v3 Import pattern: Upload → Map columns (new) → [Options] → Review (bad rows skipped, safe fixes) → Results (scheduled or now), Imports in progress card; plus Batch delete (batch table + typed-count confirm)")],-1)),i(r,{src:"/demos/src/cc/templates/ImportScreen/ImportScreen.html"}),e[4]||(e[4]=c('<h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p><code>Upload → Map columns → [Options] → Review → Results</code>, on one page, in one card, with the new <strong>Stepper</strong> under the card head and <strong>Back / primary action</strong> in the card footer. Options only appears when the import has settings (User Import has 10; Contact List Import has none, so it has 4 steps).</p><table tabindex="0"><thead><tr><th>Step</th><th>What it shows</th><th>Leaves when</th></tr></thead><tbody><tr><td>Upload</td><td>DragDropFile (XLSX or CSV, 100MB), then the file as a row: name, rows · columns · size, Replace / Remove. Wrong type / too big → DragDropFile Error + a sentence saying what to do. Sample-file link</td><td>a file is accepted</td></tr><tr><td>Map columns</td><td>One Table row per column <strong>in the user&#39;s file</strong>: name + two sample values → Select of the import&#39;s fields (+ Don&#39;t import), the field&#39;s type and help under it → status badge Matched / Changed / Not imported / Chosen twice. Fields with no column are listed under the table</td><td>no field is chosen twice, required fields have a column, and the import&#39;s own rule holds (Contact List: UserCode <strong>or</strong> Email)</td></tr><tr><td>Options</td><td>The import&#39;s settings as FieldRows (record-screen markup), v1&#39;s help text</td><td>always</td></tr><tr><td>Review</td><td>&quot;Checking N rows…&quot;, then an Alert (all ready / some skipped / none can import), three counts (Ready · Fixed for you · Will be skipped) and <strong>Rows to check</strong>: Row, Column, Value in file (spaces shown as ·), Problem, Outcome badge Skipped / Fixed / Note. Download skipped rows</td><td>≥ 1 row is ready → primary &quot;Import N rows&quot;</td></tr><tr><td>Results</td><td>Scheduled (default, v1&#39;s behaviour): &quot;Import scheduled… we&#39;ll email you at …&quot;, the run appears in <strong>Imports in progress</strong>. <code>run: &#39;now&#39;</code>: a progress bar, then &quot;Import complete&quot;. Counts + Rows to check stay. &quot;Import another file&quot;</td><td>—</td></tr></tbody></table><p><strong>Imports in progress</strong> (v1&#39;s TaskProgress panel) is a card above the flow, shown only when this user has an unfinished run: ID, Progress (n of N + bar), Started by, Started, Last run.</p><h2 id="decisions-mark-2026-10-22-unless-noted" tabindex="-1">Decisions (Mark, 2026-10-22, unless noted) <a class="header-anchor" href="#decisions-mark-2026-10-22-unless-noted" aria-label="Permalink to &quot;Decisions (Mark, 2026-10-22, unless noted)&quot;">​</a></h2><ol><li><strong>One page + a Stepper</strong>, not stacked sections or separate pages. New component: <code>src/components/Stepper</code>.</li><li><strong>A column-mapping step</strong>, new in v3: v1 needs the file&#39;s headers to be the config&#39;s column names. Auto-match ignores case, spaces and punctuation, then tries aliases. Mappings are not saved between runs.</li><li><strong>Bad rows are skipped, not fatal.</strong> v1 rejects the whole file on any row error. Rows with errors are skipped and can be downloaded (the user&#39;s columns + an Error column), fixed and re-imported.</li><li><strong>&quot;Fixed for you&quot;</strong> is new: safe corrections (trim + lower-case an email, <code>;</code> or <code>,</code> → <code>|</code> between list IDs) are applied and listed, rather than failing the row. <strong>Note</strong> = worth knowing, changes nothing (the same contact twice).</li><li><strong>XLSX and CSV.</strong> v1 takes .xlsx only. CSV is new for backend.</li><li><strong>Batch delete is its own screen, not an import.</strong> v1 doesn&#39;t take a file: it lists the batches earlier imports created. v3: a table of batches (tick, Batch reference, Users, Imported, Imported by) → Alert button &quot;Delete N users&quot; → confirm modal that names the batches and stays disabled until <strong>N is typed</strong> → &quot;Delete scheduled&quot;. Deleted batches (v1&#39;s audit) below.</li><li>Header: one secondary (<strong>Sample file</strong>), anything else in the kebab (CC header rule). User Import&#39;s &quot;Batch delete users&quot; is in the kebab; the batch screen links back with <strong>User import</strong>.</li><li>Copy names the outcome and what to do next; no &quot;Error!&quot; headings; counts go in neutral chips.</li></ol><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>ControlScreen shell (cloned from ExportSystem) · RecordSection · <strong>Stepper (new)</strong> · DragDropFile · Button (primary / secondary / tertiary / alert) · Select · Table · Badge · Alert · Spinner · FieldRow + Radio + Input + Select (Options) · Modal <code>--confirm</code> + Input (batch delete).</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed; no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed; no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>Borrowed from</th></tr></thead><tbody><tr><td>Page card gap</td><td><code>spacing-5</code> (0 full width)</td><td>ExportSystem / record screens</td></tr><tr><td>Top-level cards</td><td><code>border/card</code>, <code>shadow/2xs</code></td><td>CC top-level card rule</td></tr><tr><td>Stepper row / footer padding</td><td><code>spacing-4</code> × <code>spacing-6</code> (<code>spacing-5</code> narrow)</td><td>RecordSection body padding</td></tr><tr><td>Panel inner gap</td><td><code>spacing-5</code></td><td>The page&#39;s card gap</td></tr><tr><td>Options row gap</td><td><code>spacing-6</code></td><td>RecordSection row gap (2026-09-29)</td></tr><tr><td>Lead text measure</td><td><code>size-12</code></td><td>Listing&#39;s widest column cap</td></tr><tr><td>File icon tile</td><td><code>spacing-8</code> square, <code>radius-md</code>, <code>surface/brand-soft-extra</code> + <code>icon/brand</code></td><td>DragDropFile icon circle + Button height</td></tr><tr><td>Inner cards (file row, tables, count tiles)</td><td><code>1px border/secondary</code>, <code>radius-md</code></td><td>Cards inside a top-level card rule</td></tr><tr><td>Mapping Select width</td><td><code>size-3</code> … <code>size-6</code></td><td>Listing column floors</td></tr><tr><td>Count tile min width</td><td><code>size-2</code></td><td>—</td></tr><tr><td>Count value</td><td><code>font-fixed-2xl</code> semibold, <code>leading-lg</code></td><td>StatCard scale</td></tr><tr><td>Progress bar</td><td><code>spacing-1</code> high, <code>surface/secondary</code> track, <code>surface/brand</code> fill</td><td>Stepper connector colours</td></tr><tr><td>DragDropFile height</td><td><code>min-height: 0</code> (component&#39;s 280px is for a bare page)</td><td>contextual override, scoped to <code>.cc-import</code></td></tr></tbody></table><h2 id="responsive-cs-page-767" tabindex="-1">Responsive (<code>cs-page</code>, 767) <a class="header-anchor" href="#responsive-cs-page-767" aria-label="Permalink to &quot;Responsive (`cs-page`, 767)&quot;">​</a></h2><p>Below 767: the Map table and the Rows-to-check table become one block per row (no sideways scroll); the Stepper shows only the current label (its own container, 640); the footer stacks with the primary action first and full width; Replace / Remove go icon-only. The Imports-in-progress and batch tables scroll inside their cards. Checked headless at 1440 and 500 (Chrome&#39;s floor).</p><h2 id="demo-switches" tabindex="-1">Demo switches <a class="header-anchor" href="#demo-switches" aria-label="Permalink to &quot;Demo switches&quot;">​</a></h2><p><code>?step=map|options|review|results</code> · <code>?run=now</code> · <code>?progress=0</code> · <code>?upload=type|size</code> · <code>?clean=1</code>. Any picked .xlsx/.csv loads the page&#39;s demo file (Cat&#39;s Contact List sample, with her awkward rows).</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><p><code>HANDOVER.md</code> § Surface: ImportScreen, and <code>grep -rn &quot;TODO(backend:ImportScreen)&quot; src/</code>.</p>',16))])}const k=a(l,[["render",p]]);export{f as __pageData,k as default};
